package org.sebi;

import io.quarkiverse.mcp.server.Tool;
import io.quarkiverse.mcp.server.ToolArg;
import io.quarkiverse.mcp.server.ToolResponse;
import io.quarkiverse.mcp.server.Prompt;
import io.quarkiverse.mcp.server.PromptArg;
import io.quarkiverse.mcp.server.PromptMessage;
import io.quarkiverse.mcp.server.ResourceTemplate;
import io.quarkiverse.mcp.server.ResourceTemplateArg;
import io.quarkiverse.mcp.server.TextResourceContents;
import jakarta.enterprise.context.ApplicationScoped;
import jakarta.inject.Inject;
import java.util.ArrayList;
import java.util.List;

@ApplicationScoped
public class CatalogueMcpServer {

    @Inject
    CatalogueService catalogue;

    @Tool(description = "Recherche des services du catalogue par nom ou par équipe. Retourne la liste mise en forme (nom, équipe, criticité).")
    public ToolResponse find_service(
            @ToolArg(description = "Texte à rechercher dans le nom du service ou de l'équipe (insensible à la casse).") String query) {
        List<CatalogueService.Service> results = catalogue.findService(query);
        return ToolResponse.success(formatList(results));
    }

    @Tool(description = "Renvoie l'équipe propriétaire et la criticité d'un service à partir de son nom exact.")
    public ToolResponse get_owner(
            @ToolArg(description = "Nom exact du service (ex: 'auth', 'facturation').") String service) {
        CatalogueService.Service s = catalogue.getByName(service);
        if (s == null) {
            return ToolResponse.success("Service '" + service + "' introuvable dans le catalogue.");
        }
        StringBuilder sb = new StringBuilder();
        sb.append("Service : ").append(s.name()).append('\n');
        sb.append("Équipe propriétaire : ").append(s.equipe()).append('\n');
        sb.append("Criticité : ").append(s.criticite()).append('\n');
        if (s.depend_de() != null && !s.depend_de().isEmpty()) {
            sb.append("Dépendances : ").append(String.join(", ", s.depend_de())).append('\n');
        }
        return ToolResponse.success(sb.toString().trim());
    }

    @ResourceTemplate(uriTemplate = "service://{name}",
            description = "Fiche complète d'un service (équipe, criticité, dépendances).")
    public TextResourceContents service_fiche(
            @ResourceTemplateArg(name = "name") String name) {
        CatalogueService.Service s = catalogue.getByName(name);
        String body = s == null ? "Service '" + name + "' introuvable." : formatService(s);
        return new TextResourceContents("service://" + (s == null ? name : s.name()), body, "text/plain");
    }

    @Prompt(name = "fiche_service",
            description = "Gabarit de synthèse pour l'astreinte : produit une fiche concise d'un service à partir de son nom.")
    public List<PromptMessage> fiche_service(
            @PromptArg(name = "service", description = "Nom du service à présenter.", required = true) String service) {
        CatalogueService.Service s = catalogue.getByName(service);
        String ctx = s == null
                ? "Le service '" + service + "' est introuvable dans le catalogue."
                : formatService(s);
        List<PromptMessage> out = new ArrayList<>();
        out.add(PromptMessage.withAssistantRole(
                "Tu es l'assistant d'astreinte. À partir des informations ci-dessous, "
                        + "produis une fiche concise (5 lignes max) indiquant : équipe, criticité, "
                        + "dépendances à surveiller, et première action recommandée."));
        out.add(PromptMessage.withUserRole(
                "Service demandé : " + service + "\n\nDonnées du catalogue :\n" + ctx));
        return out;
    }

    private static String formatList(List<CatalogueService.Service> results) {
        if (results.isEmpty()) {
            return "Aucun service trouvé.";
        }
        StringBuilder sb = new StringBuilder();
        sb.append("Services trouvés (").append(results.size()).append(") :\n");
        for (CatalogueService.Service s : results) {
            sb.append(" - ").append(s.name())
                    .append(" | équipe: ").append(s.equipe())
                    .append(" | criticité: ").append(s.criticite()).append('\n');
        }
        return sb.toString().trim();
    }

    private static String formatService(CatalogueService.Service s) {
        StringBuilder sb = new StringBuilder();
        sb.append("Nom : ").append(s.name()).append('\n');
        sb.append("Équipe : ").append(s.equipe()).append('\n');
        sb.append("Criticité : ").append(s.criticite()).append('\n');
        sb.append("Dépendances : ").append(
                (s.depend_de() == null || s.depend_de().isEmpty())
                        ? "aucune"
                        : String.join(", ", s.depend_de()));
        return sb.toString();
    }
}

