package org.sebi;

import com.fasterxml.jackson.annotation.JsonIgnoreProperties;
import com.fasterxml.jackson.databind.ObjectMapper;
import jakarta.enterprise.context.ApplicationScoped;
import java.io.IOException;
import java.io.InputStream;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Locale;

@ApplicationScoped
public class CatalogueService {

    private List<Service> services;

    public void init() {
        ObjectMapper mapper = new ObjectMapper();
        try (InputStream is = Thread.currentThread().getContextClassLoader()
                .getResourceAsStream("catalogue-services.json")) {
            if (is == null) {
                throw new IllegalStateException("catalogue-services.json introuvable sur le classpath");
            }
            CatalogueFile root = mapper.readValue(is, CatalogueFile.class);
            this.services = root.services == null ? List.of() : List.copyOf(root.services);
        } catch (IOException e) {
            throw new IllegalStateException("Impossible de charger catalogue-services.json", e);
        }
    }

    public List<Service> findService(String query) {
        if (services == null) {
            init();
        }
        if (query == null || query.isBlank()) {
            return Collections.unmodifiableList(services);
        }
        String needle = query.toLowerCase(Locale.ROOT);
        List<Service> matches = new ArrayList<>();
        for (Service s : services) {
            if (s.name().toLowerCase(Locale.ROOT).contains(needle)
                    || s.equipe().toLowerCase(Locale.ROOT).contains(needle)) {
                matches.add(s);
            }
        }
        return matches;
    }

    public Service getByName(String name) {
        if (services == null) {
            init();
        }
        if (name == null) {
            return null;
        }
        for (Service s : services) {
            if (s.name().equalsIgnoreCase(name)) {
                return s;
            }
        }
        return null;
    }

    public List<Service> all() {
        if (services == null) {
            init();
        }
        return Collections.unmodifiableList(services);
    }

    @JsonIgnoreProperties(ignoreUnknown = true)
    public static final class CatalogueFile {
        public List<Service> services;
    }

    @JsonIgnoreProperties(ignoreUnknown = true)
    public record Service(String name, String equipe, String criticite, List<String> depend_de) {
    }
}
